38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
44		StatusInvalid         = "invalid_parameter"
45		StatusStorage         = "storage_error"
46		StatusRefundSuccess   = "refunded"         // 成功全额退回
47		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
48		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
49	)
